import{z as n,x as d,o as E,c as B,q as r,j as A,D as s,d as t,s as i,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"RISC-V 虚拟化 H 扩展","description":"","frontmatter":{"title":"RISC-V 虚拟化 H 扩展","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/riscv-h-extension.md","filePath":"cs/riscv-h-extension.md","lastUpdated":1791413859000}'),p={name:"cs/riscv-h-extension.md"};function c(S,e,h,V,C,g){const o=d("Mermaid");return E(),B("div",null,[e[2]||(e[2]=r('<h1 id="risc-v-虚拟化-h-扩展" tabindex="-1">RISC-V 虚拟化 H 扩展 <a class="header-anchor" href="#risc-v-虚拟化-h-扩展" aria-label="Permalink to &quot;RISC-V 虚拟化 H 扩展&quot;">​</a></h1><div class="epigraph"><p>H 扩展给 S 态加上 hypervisor：客机仍走自己的 Sv39，客物理地址再经 G-stage 译到宿主物理地址，影子页表不必跟每一次客内核填 PTE。</p><footer>—— 据 The RISC-V Instruction Set Manual, Volume II: Privileged Architecture；ARM ARM（EL2 / Stage-2）；Intel SDM（EPT）整理</footer></div><p><a href="/cs/sv39-page-table">上一课</a>钉的是单层 <code>satp</code>。<a href="/cs/ept-npt">EPT 与 NPT</a> 已在 x86 侧讲过两层翻译。<a href="/cs/arm-vs-riscv">ARM 对 RISC-V</a> 把虚拟化对照留在 EL2。缺口是 <strong>RISC-V H</strong>：VS/VU 模式与 <code>hgatp</code>，而不是再画一遍三级 VPN。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有 H 时，VMM 只能用影子页表，或把客内核当用户进程跑。<a href="/cs/sv39-page-table">Sv39</a> 的 <code>satp</code> 只有一套根。H 扩展引入：HS（hypervisor 扩展的 S）、VS（虚拟 S）、VU（虚拟 U）。客 OS 以为自己在写 <code>satp</code>，硬件实际用 VS-stage 把 GVA→GPA，再用 <code>hgatp</code> 的 G-stage 把 GPA→HPA。<span class="marginnote">直觉类比：两阶段翻译像挂号信——客内核按自己城市（GPA）填地址，邮局（G-stage）再把城市名换算成真实门牌（HPA）。客内核永远不知道真实门牌被换过，这就是隔离的来源。</span>缺口不是再解释「什么是虚拟机」，而是<strong>第二层页表挂在哪颗 CSR 上</strong>。</p><p>两层都可以缺：VS 缺页交给客内核；G-stage 缺页（GPA 未映射）交给 hypervisor，对应 EPT violation。</p><h3 id="h-不是「再开一个-m-态」" tabindex="-1">H 不是「再开一个 M 态」 <a class="header-anchor" href="#h-不是「再开一个-m-态」" aria-label="Permalink to &quot;H 不是「再开一个 M 态」&quot;">​</a></h3><p>M 态仍是最高。Hypervisor 跑在 HS，不靠把全部敏感指令降到机器态模拟。把 H 理解成第三份 RV32I，对照课会失去两阶段 MMU。也不把本课写成某开源 hypervisor 的启动日志。</p><p><span class="marginnote">RISC-V Privileged Spec 的 Hypervisor 章是权威。ARM Stage-2 与 Intel EPT 是对照，不在本课重写项格式。本课不背 <code>hstatus</code> 每一位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>VMM 为每个客机配置 <code>hgatp</code>（G-stage 根，格式可与 Sv39 同类树）。客内核照常填自己的页表。取指与 load/store 经两层；TLB 缓存组合结果，<code>HFENCE.VVMA</code> / <code>HFENCE.GVMA</code> 分别冲客与 G-stage，对象不是 <a href="/cs/fence-instructions">内存 fence</a>。<span class="marginnote">「HFENCE」翻译成大白话：冲 TLB 的专用指令。VVMA 冲「某客机某地址空间」的旧翻译，GVMA 冲 G-stage 的旧翻译——两层各有一份缓存，只冲一层，另一层还会继续给出过期地址。</span></p><p>Hypervisor 需要读客虚拟地址：<code>HLV</code>/<code>HSV</code> 一类指令在 HS 按 VS 翻译访问客内存，避免自己切 <code>satp</code>。中断：注入与委托走 <code>hideleg</code>/<code>hvip</code>，对照 GIC 虚拟化，本课只点名。</p>',12)),(E(),A(l,null,{default:s(()=>[i(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GVA%5B%22%E5%AE%A2%E8%99%9A%E5%9C%B0%E5%9D%80%20GVA%22%5D%20--%3E%20VS%5B%22VS-stage%20satp%22%5D%0A%20%20VS%20--%3E%20GPA%5B%22%E5%AE%A2%E7%89%A9%E7%90%86%20GPA%22%5D%0A%20%20GPA%20--%3E%20GS%5B%22G-stage%20hgatp%22%5D%0A%20%20GS%20--%3E%20HPA%5B%22%E5%AE%BF%E4%B8%BB%E7%89%A9%E7%90%86%20HPA%22%5D%0A%20%20HPA%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%94%A8%E6%88%B7%E6%80%81%20ALU%20%E6%89%A9%E5%B1%95%E4%BB%8D%E7%BC%BA%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[t("嵌套虚拟化与 IOMMU 第二层不在本课展开；"),a("a",{href:"/cs/dma-scatter-gather"},"DMA"),t(" 的设备地址仍要 IOMMU，不是 "),a("code",null,"hgatp"),t(" 自动覆盖。")],-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,"ISA 对照轴上，H 把 RISC-V 的特权故事补到与 EL2/VMX 可引用的位置：页表格式仍是 Sv39 一类树，只是串了两次。用户态整数、压缩、向量并不因 H 改变编码。下一课位操作扩展回到 ALU：地址生成与位域仍是编译器每天发射的缺口，与虚拟化正交。",-1)),e[6]||(e[6]=a("p",null,[a("span",{class:"marginnote"},"常见误区：把 G-stage 缺页当客内核的 bug。它是 hypervisor 侧的映射问题——客物理页还没分配或被换出——修复动作发生在宿主，客内核全程不知情；VS 缺页才归客内核管。")],-1)),(E(),A(l,null,{default:s(()=>[i(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E5%AE%A2%E6%9C%BA%E8%AE%BF%E5%AD%98%EF%BC%8C%E7%A1%AC%E4%BB%B6%E5%BC%80%E5%A7%8B%E4%B8%A4%E5%B1%82%E7%BF%BB%E8%AF%91%22%5D%20--%3E%20VS%7B%22VS-stage%20%E5%91%BD%E4%B8%AD%E5%90%97%22%7D%0A%20%20VS%20--%3E%7C%22%E7%BC%BA%E9%A1%B5%22%7C%20GOS%5B%22VS%20%E7%BC%BA%E9%A1%B5%EF%BC%9A%E6%B3%A8%E5%85%A5%E5%AE%A2%E5%86%85%E6%A0%B8%EF%BC%8C%E5%AE%A2%E5%86%85%E6%A0%B8%E8%87%AA%E5%B7%B1%E5%A1%AB%20PTE%22%5D%0A%20%20VS%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20GS%7B%22G-stage%20%E5%91%BD%E4%B8%AD%E5%90%97%22%7D%0A%20%20GS%20--%3E%7C%22%E7%BC%BA%E9%A1%B5%22%7C%20VMM%5B%22G-stage%20%E7%BC%BA%E9%A1%B5%EF%BC%9A%E9%99%B7%E5%85%A5%20hypervisor%20%E8%A1%A5%E6%98%A0%E5%B0%84%22%5D%0A%20%20GS%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20OK%5B%22%E4%B8%A4%E5%B1%82%E5%90%88%E6%88%90%EF%BC%8C%E8%AE%BF%E9%97%AE%E5%AE%BF%E4%B8%BB%E7%89%A9%E7%90%86%E5%86%85%E5%AD%98%22%5D%0A"})]),fallback:s(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证某硅片已实现 H，不写 virtio 队列，不把侧信道写成利用步骤。不把 Type-1/Type-2 产品分类当 ISA 定义。</p><p>后课默认：H 扩展用 VS-stage + G-stage 两层翻译；<code>hgatp</code> 是宿主看客物理的根。下一课位操作。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VS 翻译客虚地址，G-stage 再译客物理。</li><li>对照 EPT / ARM Stage-2，CSR 与栅栏名不同。</li><li>不替代 M 态，也不改用户 ALU。</li><li>出处：RISC-V Privileged Spec（H）；ARM ARM；Intel SDM（EPT）。</li></ul>',5))])}const u=n(p,[["render",c]]);export{m as __pageData,u as default};
